```go
package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/token"
	"io/ioutil"
	"os"
)

// Define a function to generate Avro schema based on struct fields.
func generateAvroSchema(structName string) (string, error) {
	// Load the Go source code from the given file path.
	filePath := fmt.Sprintf("%s.go", structName)
	sourceCode, err := ioutil.ReadFile(filePath)
	if err != nil {
		return "", err
	}

	// Parse the Go source code into an AST.
	tree, err := token.ParseFile(token.NewFileSet(), filePath, sourceCode)
	if err != nil {
		return "", err
	}

	// Extract field names and types from the parsed AST.
	var fieldNameMap = make(map[string]*avro.FieldType)
	for _, decl := range tree.Decls[0].(*types.Struct).Fields.List {
		fieldName := decl.Name.String()
		fieldType := decl.Type.String()

		switch fieldType {
		case "int32":
			fieldTypeName := "Int"
		case "int64":
			fieldTypeName := "Long"
		case "float32":
			fieldTypeName := "Float"
		case "float64":
			fieldTypeName := "Double"
		case "bool":
			fieldTypeName := "Boolean"
		default:
			continue // Ignore unknown field types
		}
		fieldNameMap[fieldName] = &avro.FieldType{
			Name:     fieldName,
			Type:     fieldTypeName,
			Default:  "",
			Required: false,
		}
	}

	// Create an Avro schema representation based on the extracted field information.
	schemaBytes, err := json.MarshalIndent(fieldNameMap, "", "\t")
	if err != nil {
		return "", err
	}

	return string(schemaBytes), nil
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run main.go <struct_name> <output_file>")
		os.Exit(1)
	}

	structName := os.Args[1]
	outputFilePath := os.Args[2]

	schema, err := generateAvroSchema(structName)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		os.Exit(1)
	}

	err = ioutil.WriteFile(outputFilePath, []byte(schema), 0644)
	if err != nil {
		fmt.Printf("Error writing Avro schema to file: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Generated Avro schema saved to '%s'\n", outputFilePath)
}
```

### How to Use:

1. **Compile the Program**: 
   Run the following command to compile your program:
   ```bash
   go build -o generate-avro-schema .
   ```

2. **Run the Program**:
   Pass the required arguments when running the compiled program:
   ```bash
   ./generate-avro-schema MyStruct my_struct.avsc
   ```

   This example assumes you have a Go file named `MyStruct.go` containing the struct definition.

### Notes:
- Ensure that the Go source file (`MyStruct.go`) exists and contains the specified struct definition.
- Make sure the generated `.avsc` file has appropriate permissions (e.g., `0644`) so it can be read by others or yourself if needed.

